      "rationale": "P021 directly specifies the full proposed observation set."
    }
  },
  "signal_basis": {
    "component_id": "C031.signal_basis",
    "value": "Prospectively monitor the selected trial's delays, handoff timing, booking completion or displacement, workload and cleaning requirements, with specified success and acceptable workload/access criteria and stopping rules for operational harm or extra staffing.",
    "scope": "Monitoring a narrowly scoped, reversible trial; no favorable outcome is presumed.",
